#!/usr/bin/env bash
# Standalone installer. Keep the common body synchronized between the web projects.
APP=q-kanbant
SERVICE_USER=qkanbant
REPOSITORY=QRod/q_KanbanT
DEFAULT_BACKEND=5173
DB_NAME=kanbant.sqlite3
LEGACY_DB=.data/kanbant.sqlite3
ADMIN_ARGS="--create-admin"
set -Eeuo pipefail
umask 077
VERSION=latest
ADDRESS=localhost
TLS=local
PROXY=caddy
HTTPS_PORT=8443
BACKEND_PORT=$DEFAULT_BACKEND
ALLOW_CIDR=0.0.0.0/0
EMAIL=
ARCHIVE=
ARCHIVE_HASH=
MIGRATE_FROM=
PLAN=0
CONFIG=/etc/$APP/install.env
BASE=/opt/$APP
DATA=/var/lib/$APP
BACKUPS=/var/backups/$APP
# This file is generated by this installer and is root-only.
if [[ -f "$CONFIG" && $EUID == 0 ]]; then source "$CONFIG"; fi
while (($#)); do
 case "$1" in
  --version) VERSION=${2:?}; shift 2;;
  --address|--domain) ADDRESS=${2:?}; shift 2;;
  --tls) TLS=${2:?}; shift 2;;
  --proxy) PROXY=${2:?}; shift 2;;
  --https-port) HTTPS_PORT=${2:?}; shift 2;;
  --backend-port) BACKEND_PORT=${2:?}; shift 2;;
  --allow-cidr) ALLOW_CIDR=${2:?}; shift 2;;
  --email) EMAIL=${2:?}; shift 2;;
  --archive) ARCHIVE=${2:?}; shift 2;;
  --sha256) ARCHIVE_HASH=${2:?}; shift 2;;
  --migrate-from) MIGRATE_FROM=${2:?}; shift 2;;
  --plan) PLAN=1; shift;;
  --help) cat <<EOF
Instala o actualiza $APP en Linux con systemd y Python 3.11+.
Opciones:
 --version vX.Y.Z              Entrega; por defecto la última publicación
 --address IP_O_DOMINIO        Dirección para el certificado y acceso
 --tls local|public           CA local o Let's Encrypt con dominio público
 --https-port 8443            Puerto local; para TLS público usar 443
 --backend-port $DEFAULT_BACKEND    Backend en loopback
 --allow-cidr CIDR             Restringe el proxy a esta red (por defecto todas)
 --email CORREO               Requerido para TLS público
 --proxy caddy|external       Caddy incluido o proxy HTTPS ya administrado
 --migrate-from DIRECTORIO    Importa los datos de una instalación manual previa
 --archive ARCHIVO --sha256 HASH --version vX.Y.Z   Instala un artefacto local
 --plan                       Muestra la familia Linux y no realiza cambios

No actualiza automáticamente el sistema operativo ni modifica el firewall.
EOF
 exit 0;;
  *) echo "Opción desconocida: $1" >&2; exit 2;;
 esac
done
fail() { echo "ERROR: $*" >&2; exit 1; }
[[ $(uname -s) == Linux || $PLAN == 1 ]] || fail 'Se requiere Linux'
[[ -r ${Q_INSTALL_OS_RELEASE:-/etc/os-release} ]] || fail 'No se encontró os-release'
family=$(source "${Q_INSTALL_OS_RELEASE:-/etc/os-release}"; printf ' %s %s ' "${ID:-}" "${ID_LIKE:-}")
case "$family" in
 *debian*|*ubuntu*|*zorin*|*linuxmint*) MANAGER=apt;;
 *rhel*|*fedora*|*centos*|*rocky*|*almalinux*|*ol*) MANAGER=dnf;;
 *suse*|*opensuse*) MANAGER=zypper;;
 *arch*|*manjaro*|*endeavouros*) MANAGER=pacman;;
 *) fail "Familia no soportada: $family. Usa una instalación manual con Python 3.11+ y systemd.";;
esac
if ((PLAN)); then printf 'app=%s\nfamilia=%s\ngestor=%s\npython_min=3.11\nproxy=%s\ntls=%s\n' "$APP" "$family" "$MANAGER" "$PROXY" "$TLS"; exit 0; fi
[[ $EUID == 0 ]] || fail 'Ejecuta con sudo bash install.sh'
[[ -d /run/systemd/system ]] || fail 'Se requiere systemd como gestor de servicios'
[[ "$TLS" == local || "$TLS" == public ]] || fail 'TLS debe ser local o public'
[[ "$PROXY" == caddy || "$PROXY" == external ]] || fail 'Proxy debe ser caddy o external'
[[ "$ADDRESS" =~ ^[A-Za-z0-9.:-]+$ ]] || fail 'Dirección inválida'
[[ "$HTTPS_PORT" =~ ^[0-9]+$ && "$BACKEND_PORT" =~ ^[0-9]+$ ]] || fail 'Puertos inválidos'
((HTTPS_PORT>=1 && HTTPS_PORT<=65535 && BACKEND_PORT>=1024 && BACKEND_PORT<=65535 && HTTPS_PORT!=BACKEND_PORT)) || fail 'Puertos fuera de rango'
[[ "$VERSION" == latest || "$VERSION" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || fail 'Usa una etiqueta vX.Y.Z'
if [[ "$TLS" == public ]]; then
 [[ "$ADDRESS" =~ ^[A-Za-z0-9][A-Za-z0-9.-]+\.[A-Za-z]{2,}$ && "$EMAIL" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+$ && "$HTTPS_PORT" == 443 ]] || fail 'TLS público requiere dominio, --email y --https-port 443'
fi
case "$MANAGER" in
 apt) export DEBIAN_FRONTEND=noninteractive; apt-get update; apt-get install -y python3 python3-venv python3-pip ca-certificates curl tar openssl util-linux iproute2;;
 dnf) dnf install -y python3 ca-certificates curl tar openssl util-linux iproute shadow-utils; if ! python3 -c 'import sys; assert sys.version_info >= (3,11)' 2>/dev/null; then dnf install -y python3.11 python3.11-pip; fi;;
 zypper) zypper --non-interactive install python311 python311-pip ca-certificates curl tar openssl util-linux iproute2 shadow;;
 pacman) pacman -S --needed --noconfirm python python-pip ca-certificates curl tar openssl util-linux iproute2 shadow;;
esac
PYTHON=
for candidate in python3 python3.13 python3.12 python3.11; do
 if command -v "$candidate" >/dev/null && "$candidate" -c 'import sys; assert sys.version_info >= (3,11)' 2>/dev/null; then PYTHON=$(command -v "$candidate"); break; fi
done
[[ -n "$PYTHON" ]] || fail 'Instala Python 3.11 o posterior desde los repositorios de tu distribución'
"$PYTHON" - "$ADDRESS" "$ALLOW_CIDR" <<'PY'
import ipaddress,re,sys
address,network=sys.argv[1:]
try: ipaddress.ip_address(address)
except ValueError:
 if not re.fullmatch(r'[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?',address):raise SystemExit('Dirección inválida')
ipaddress.ip_network(network,strict=False)
PY
exec 9>"/run/lock/$APP-install.lock"
flock -n 9 || fail 'Ya hay otra instalación en curso'
WORK=$(mktemp -d "/var/tmp/$APP-install.XXXXXX")
CUTOVER=0
OLD_CURRENT=$(readlink -f "$BASE/current" 2>/dev/null || true)
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
mkdir -p "$BACKUPS/$STAMP" "$BASE/releases" "/etc/$APP" "$DATA"
chmod 755 "$BASE" "$BASE/releases"
chmod 700 "$BACKUPS" "$BACKUPS/$STAMP" "/etc/$APP"
for unit in "$APP" "$APP-proxy"; do
 [[ ! -f /etc/systemd/system/$unit.service ]] || cp -p "/etc/systemd/system/$unit.service" "$BACKUPS/$STAMP/$unit.service"
done
[[ ! -f "$CONFIG" ]] || cp -p "$CONFIG" "$BACKUPS/$STAMP/install.env"
[[ ! -f /etc/$APP/runtime.env ]] || cp -p "/etc/$APP/runtime.env" "$BACKUPS/$STAMP/runtime.env"
[[ ! -f /etc/$APP-proxy/Caddyfile ]] || cp -p "/etc/$APP-proxy/Caddyfile" "$BACKUPS/$STAMP/Caddyfile"
rollback() {
 code=$?; trap - ERR
 if ((CUTOVER)); then
  echo 'La comprobación falló. Restaurando servicio y base anteriores.' >&2
  systemctl stop "$APP" "$APP-proxy" 2>/dev/null || true
  if [[ -n "$OLD_CURRENT" ]]; then ln -sfn "$OLD_CURRENT" "$BASE/current"; fi
  if [[ -f "$BACKUPS/$STAMP/database.sqlite3" ]]; then
   "$PYTHON" - "$BACKUPS/$STAMP/database.sqlite3" "$DATA/$DB_NAME" <<'PY'
import sqlite3,sys
with sqlite3.connect(sys.argv[1]) as src,sqlite3.connect(sys.argv[2]) as dst:src.backup(dst)
PY
  fi
  for unit in "$APP" "$APP-proxy"; do
   if [[ -f "$BACKUPS/$STAMP/$unit.service" ]]; then cp -p "$BACKUPS/$STAMP/$unit.service" "/etc/systemd/system/$unit.service"; fi
  done
  if [[ -f "$BACKUPS/$STAMP/install.env" ]]; then cp -p "$BACKUPS/$STAMP/install.env" "$CONFIG"; fi
  if [[ -f "$BACKUPS/$STAMP/runtime.env" ]]; then cp -p "$BACKUPS/$STAMP/runtime.env" "/etc/$APP/runtime.env"; fi
  if [[ -f "$BACKUPS/$STAMP/Caddyfile" ]]; then cp -p "$BACKUPS/$STAMP/Caddyfile" "/etc/$APP-proxy/Caddyfile"; fi
  chown -R "$SERVICE_USER:$SERVICE_USER" "$DATA"
  systemctl daemon-reload
  if [[ -f "$BACKUPS/$STAMP/$APP.service" ]]; then systemctl start "$APP" || true; fi
  if [[ -f "$BACKUPS/$STAMP/$APP-proxy.service" ]]; then systemctl start "$APP-proxy" || true; fi
 fi
 echo "Instalación incompleta. Diagnóstico: journalctl -u $APP -u $APP-proxy; respaldo: $BACKUPS/$STAMP" >&2
 exit "$code"
}
trap rollback ERR
fetch() { curl --proto '=https' --tlsv1.2 -fsSL --retry 3 "$1" -o "$2"; }
if [[ -z "$ARCHIVE" ]]; then
 if [[ "$VERSION" == latest ]]; then
  fetch "https://api.github.com/repos/$REPOSITORY/releases/latest" "$WORK/release.json"
  VERSION=$("$PYTHON" -c 'import json,sys;print(json.load(open(sys.argv[1]))["tag_name"])' "$WORK/release.json")
 fi
 [[ "$VERSION" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || fail 'Etiqueta de entrega inválida'
 ASSET="$APP-$VERSION.tar.gz"
 fetch "https://github.com/$REPOSITORY/releases/download/$VERSION/$ASSET" "$WORK/$ASSET"
 fetch "https://github.com/$REPOSITORY/releases/download/$VERSION/SHA256SUMS" "$WORK/SHA256SUMS"
 ARCHIVE_HASH=$(awk -v f="$ASSET" '$2==f {print $1}' "$WORK/SHA256SUMS")
 ARCHIVE="$WORK/$ASSET"
fi
[[ "$VERSION" != latest && "$ARCHIVE_HASH" =~ ^[a-fA-F0-9]{64}$ ]] || fail 'El artefacto local requiere --version y --sha256 válidos'
printf '%s  %s\n' "$ARCHIVE_HASH" "$ARCHIVE" | sha256sum -c -
RELEASE="$BASE/releases/$VERSION"
if [[ -f "$RELEASE/.ready" ]]; then
 [[ $(cat "$RELEASE/.archive-sha256") == "$ARCHIVE_HASH" ]] || fail 'Ya existe esta versión con un contenido diferente'
else
 [[ ! -e "$RELEASE" ]] || fail "Existe una instalación incompleta en $RELEASE; revísala antes de reintentar"
 mkdir -p "$RELEASE"
 "$PYTHON" - "$ARCHIVE" "$RELEASE" <<'PY'
import pathlib,sys,tarfile
root=pathlib.Path(sys.argv[2]).resolve()
with tarfile.open(sys.argv[1]) as archive:
 for member in archive.getmembers():
  target=(root/member.name).resolve()
  if not target.is_relative_to(root) or not (member.isfile() or member.isdir()):raise SystemExit('Archivo inseguro en el paquete')
 archive.extractall(root,filter='data') if sys.version_info >= (3,12) else archive.extractall(root)
PY
 "$PYTHON" -m venv "$RELEASE/.venv"
 if [[ -s "$RELEASE/requirements.txt" ]]; then "$RELEASE/.venv/bin/python" -m pip install -r "$RELEASE/requirements.txt"; fi
 printf '%s' "$ARCHIVE_HASH" > "$RELEASE/.archive-sha256"
 touch "$RELEASE/.ready"
 chmod -R a+rX,go-w "$RELEASE"
fi
getent group "$SERVICE_USER" >/dev/null || groupadd --system "$SERVICE_USER"
id "$SERVICE_USER" >/dev/null 2>&1 || useradd --system --gid "$SERVICE_USER" --home-dir "$DATA" --shell /usr/sbin/nologin "$SERVICE_USER"
chown -R "$SERVICE_USER:$SERVICE_USER" "$DATA"
# Check port conflicts before interrupting the existing application.
if [[ "$PROXY" == caddy ]] && ! systemctl is-active --quiet "$APP-proxy"; then
 if ss -H -ltn "sport = :$HTTPS_PORT" | read -r _; then fail "Puerto HTTPS $HTTPS_PORT ocupado; usa otro o --proxy external"; fi
 if [[ "$TLS" == public ]] && ss -H -ltn 'sport = :80' | read -r _; then fail 'Puerto 80 ocupado; usa --proxy external o un proxy compartido'; fi
fi
if [[ "$PROXY" == caddy ]]; then
 PROXY_USER="${SERVICE_USER}proxy"
 PROXY_DATA="/var/lib/$APP-proxy"
 getent group "$PROXY_USER" >/dev/null || groupadd --system "$PROXY_USER"
 id "$PROXY_USER" >/dev/null 2>&1 || useradd --system --gid "$PROXY_USER" --home-dir "$PROXY_DATA" --shell /usr/sbin/nologin "$PROXY_USER"
 install -d -m 750 -o root -g "$PROXY_USER" "/etc/$APP-proxy"
 install -d -m 700 -o "$PROXY_USER" -g "$PROXY_USER" "$PROXY_DATA"
 CADDY_VERSION=2.11.7
 case $(uname -m) in
 x86_64) CADDY_ARCH=amd64; CADDY_HASH=a7a433a1b133efc3c8d10eb0b99d52a24b5ef5c322dc77f5282182b1c0402139ab83f3a99f0c52409df77d20123fb0b523edad8a66d8f5e49136197bf61ef0e7;;
 aarch64|arm64) CADDY_ARCH=arm64; CADDY_HASH=3db36ba90c7a6e8dda40ee3dd71fa08844c76b5fb08f61b31e5e78d2ed38e71c51dc7baed875e50d1ca1279196e84302967237386ae87c91ae9f2aaceada682e;;
 *) fail 'Proxy incluido disponible para Linux x86_64 y ARM64; usa --proxy external en otras arquitecturas';;
 esac
 mkdir -p "$BASE/tools"
 chmod 755 "$BASE/tools"
 if [[ ! -x "$BASE/tools/caddy-$CADDY_VERSION" ]]; then
  fetch "https://github.com/caddyserver/caddy/releases/download/v$CADDY_VERSION/caddy_${CADDY_VERSION}_linux_${CADDY_ARCH}.tar.gz" "$WORK/caddy.tar.gz"
  printf '%s  %s\n' "$CADDY_HASH" "$WORK/caddy.tar.gz" | sha512sum -c -
  tar -xzf "$WORK/caddy.tar.gz" -C "$WORK" caddy
  install -m 755 "$WORK/caddy" "$BASE/tools/caddy-$CADDY_VERSION"
 fi
 ln -sfn "$BASE/tools/caddy-$CADDY_VERSION" "$BASE/tools/caddy"
 AUTHORITY=$ADDRESS
 [[ "$ADDRESS" != *:* ]] || AUTHORITY="[$ADDRESS]"
 if [[ "$TLS" == local ]]; then
  GLOBALS='auto_https disable_redirects'; TLS_LINE='tls internal'
 else
  GLOBALS="email $EMAIL"; TLS_LINE='tls { issuer acme { dir https://acme-v02.api.letsencrypt.org/directory } }'
 fi
 cat > "$WORK/Caddyfile" <<EOF
{
 admin off
 skip_install_trust
 $GLOBALS
}
https://$AUTHORITY:$HTTPS_PORT {
 $TLS_LINE
 @denied not remote_ip 127.0.0.1 ::1 $ALLOW_CIDR
 respond @denied 403
 reverse_proxy 127.0.0.1:$BACKEND_PORT
}
EOF
 # Expand the public TLS block onto individual lines for the Caddyfile parser.
 if [[ "$TLS" == public ]]; then
  "$PYTHON" - "$WORK/Caddyfile" <<'PY'
import pathlib,sys
p=pathlib.Path(sys.argv[1]);p.write_text(p.read_text().replace('tls { issuer acme { dir https://acme-v02.api.letsencrypt.org/directory } }','tls {\n issuer acme {\n dir https://acme-v02.api.letsencrypt.org/directory\n }\n }'))
PY
 fi
 install -m 640 -o root -g "$PROXY_USER" "$WORK/Caddyfile" "/etc/$APP-proxy/Caddyfile.new"
 runuser -u "$PROXY_USER" -- env XDG_DATA_HOME="$PROXY_DATA" "$BASE/tools/caddy" validate --config "/etc/$APP-proxy/Caddyfile.new" --adapter caddyfile
fi
CUTOVER=1
systemctl stop "$APP" 2>/dev/null || true
if [[ -n "$MIGRATE_FROM" && ! -f "$DATA/$DB_NAME" ]]; then
 [[ "$MIGRATE_FROM" == /* && -f "$MIGRATE_FROM/$LEGACY_DB" ]] || fail 'No se encontró la base de datos de origen'
 "$PYTHON" - "$MIGRATE_FROM/$LEGACY_DB" "$DATA/$DB_NAME" <<'PY'
import sqlite3,sys
with sqlite3.connect(sys.argv[1]) as src,sqlite3.connect(sys.argv[2]) as dst:src.backup(dst)
PY
 if [[ -f "$MIGRATE_FROM/data/ssh_known_hosts" ]]; then cp "$MIGRATE_FROM/data/ssh_known_hosts" "$DATA/ssh_known_hosts"; fi
fi
if [[ -f "$DATA/$DB_NAME" ]]; then
 "$PYTHON" - "$DATA/$DB_NAME" "$BACKUPS/$STAMP/database.sqlite3" <<'PY'
import sqlite3,sys
with sqlite3.connect(sys.argv[1]) as src,sqlite3.connect(sys.argv[2]) as dst:src.backup(dst)
PY
fi
KEY_DIRECTIVE=
if [[ "$APP" == q-inv ]]; then
 if [[ ! -f /etc/q-inv/credentials.key ]]; then
  "$RELEASE/.venv/bin/python" -c 'import os;from cryptography.fernet import Fernet;fd=os.open("/etc/q-inv/credentials.key",os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600);os.write(fd,Fernet.generate_key());os.close(fd)'
 fi
 SYSTEMD_VERSION=$(systemctl --version | head -n 1 | awk '{print $2}')
 if ((SYSTEMD_VERSION>=247)); then
  KEY_DIRECTIVE='LoadCredential=ssh_key:/etc/q-inv/credentials.key'
  KEY_PATH='%d/ssh_key'
 else
  chown "$SERVICE_USER:$SERVICE_USER" /etc/q-inv/credentials.key
  chmod 400 /etc/q-inv/credentials.key
  chown "root:$SERVICE_USER" /etc/q-inv; chmod 750 /etc/q-inv
  KEY_PATH=/etc/q-inv/credentials.key
 fi
 APP_ENV="QINV_DATA=$DATA
QINV_KEY_FILE=$KEY_PATH
QINV_SECURE_COOKIE=1"
 APP_ARGS="--host 127.0.0.1 --port $BACKEND_PORT"
else
 APP_ENV="QKT_DATABASE=$DATA/$DB_NAME
QKT_SECURE_COOKIE=1
QKT_DISABLE_WEB_SETUP=1
QKT_PUBLIC_ORIGIN=https://$ADDRESS:$HTTPS_PORT"
 [[ "$HTTPS_PORT" != 443 ]] || APP_ENV=${APP_ENV/https:\/\/$ADDRESS:443/https:\/\/$ADDRESS}
 APP_ARGS="--port $BACKEND_PORT --database $DATA/$DB_NAME"
fi
# EnvironmentFile does not expand %d: use the unit's Environment= for the key.
printf '%s\n' "$APP_ENV" | grep -v '^QINV_KEY_FILE=' > "/etc/$APP/runtime.env"
chmod 600 "/etc/$APP/runtime.env"
cat > "/etc/systemd/system/$APP.service" <<EOF
[Unit]
Description=$APP web application
After=network.target
[Service]
Type=simple
User=$SERVICE_USER
Group=$SERVICE_USER
WorkingDirectory=$BASE/current
EnvironmentFile=/etc/$APP/runtime.env
Environment=PYTHONDONTWRITEBYTECODE=1
$KEY_DIRECTIVE
EOF
[[ "$APP" != q-inv ]] || printf 'Environment=QINV_KEY_FILE=%s\n' "$KEY_PATH" >> "/etc/systemd/system/$APP.service"
cat >> "/etc/systemd/system/$APP.service" <<EOF
ExecStart=$BASE/current/.venv/bin/python $BASE/current/server.py $APP_ARGS
Restart=on-failure
RestartSec=5
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=$DATA
[Install]
WantedBy=multi-user.target
EOF
if [[ "$PROXY" == caddy ]]; then
 mv "/etc/$APP-proxy/Caddyfile.new" "/etc/$APP-proxy/Caddyfile"
 cat > "/etc/systemd/system/$APP-proxy.service" <<EOF
[Unit]
Description=$APP HTTPS proxy
After=network-online.target $APP.service
Wants=network-online.target
[Service]
User=$PROXY_USER
Group=$PROXY_USER
Environment=XDG_DATA_HOME=$PROXY_DATA
Environment=XDG_CONFIG_HOME=$PROXY_DATA/config
ExecStart=$BASE/tools/caddy run --config /etc/$APP-proxy/Caddyfile --adapter caddyfile
Restart=on-failure
RestartSec=5
AmbientCapabilities=CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=$PROXY_DATA
[Install]
WantedBy=multi-user.target
EOF
fi
chown -R "$SERVICE_USER:$SERVICE_USER" "$DATA"
ln -sfn "$RELEASE" "$BASE/current"
for variable in ADDRESS TLS PROXY HTTPS_PORT BACKEND_PORT ALLOW_CIDR EMAIL; do printf '%s=%q\n' "$variable" "${!variable}"; done > "$CONFIG"
printf 'INSTALLED_VERSION=%q\n' "$VERSION" >> "$CONFIG"
chmod 600 "$CONFIG"
cat > "/usr/local/sbin/$APP-admin" <<EOF
#!/usr/bin/env bash
set -Eeuo pipefail
[[ \$EUID == 0 ]] || { echo 'Ejecuta con sudo'; exit 1; }
trap 'chown -R $SERVICE_USER:$SERVICE_USER $DATA; systemctl start $APP' EXIT
systemctl stop $APP
export QINV_DATA=$DATA QINV_KEY_FILE=/etc/q-inv/credentials.key QKT_DATABASE=$DATA/$DB_NAME
$BASE/current/.venv/bin/python $BASE/current/server.py "\$@"
EOF
chmod 750 "/usr/local/sbin/$APP-admin"
systemctl daemon-reload
systemctl enable "$APP"
systemctl restart "$APP"
READY=0
for _ in {1..30}; do
 if curl -fsS "http://127.0.0.1:$BACKEND_PORT/api/session" >/dev/null; then READY=1; break; fi
 sleep 1
done
((READY))
if [[ "$PROXY" == caddy ]]; then
 systemctl enable "$APP-proxy"
 systemctl restart "$APP-proxy"
 READY=0
 for _ in {1..30}; do
  if curl -kfsS --resolve "$AUTHORITY:$HTTPS_PORT:127.0.0.1" "https://$AUTHORITY:$HTTPS_PORT/" >/dev/null; then READY=1; break; fi
  sleep 1
 done
 ((READY))
fi
CUTOVER=0
printf '\n%s %s instalado. URL: https://%s:%s\n' "$APP" "$VERSION" "$ADDRESS" "$HTTPS_PORT"
printf 'Datos: %s\nConfiguración: /etc/%s\nRespaldo previo: %s/%s\n' "$DATA" "$APP" "$BACKUPS" "$STAMP"
printf 'Primera cuenta: sudo %s-admin %s\n' "$APP" "$ADMIN_ARGS"
if [[ "$TLS" == local ]]; then echo 'El certificado local requiere confiar en su CA desde el equipo cliente; el navegador mostrará una advertencia inicialmente.'; fi
if [[ "$TLS" == public ]]; then echo 'Verifica el certificado público desde un cliente sin -k. DNS y puertos 80/443 deben ser accesibles desde Internet.'; fi
echo 'No se modificó el firewall. Abre el puerto HTTPS elegido si tu política lo requiere.'
